"""Immutable packet records.

A packet's identity, rank and lag bookkeeping anchor are fixed when it is
admitted and never change afterwards.  That immutability is what allows
checkpoint snapshots to share packet objects between branches: only the
container roots differ between versions.
"""


class Pkt:
    """One admitted (or attempted) packet.

    ``key`` packs ``(rank, ordinal)`` into a single comparable integer so that
    priority-ordered containers need no tuple keys.  ``base`` records the
    live-overtake watermark at admission, from which the current lag is
    derived lazily.
    """

    __slots__ = ('pktid', 'flow', 'length', 'flow_size', 'rank', 'oid',
                 'key', 'base', 'bank')

    def __init__(self, pktid, flow, length, flow_size):
        self.pktid = pktid
        self.flow = flow
        self.length = length
        self.flow_size = flow_size
        self.rank = 0
        self.oid = 0
        self.key = 0
        self.base = 0
        self.bank = -1

    def __repr__(self):  # pragma: no cover - debugging aid
        return ('Pkt(id=%r flow=%r len=%r rank=%r oid=%r bank=%r)'
                % (self.pktid, self.flow, self.length, self.rank, self.oid,
                   self.bank))
PYEOF
cat > /workspace/submission/algorithms.py <<'PYEOF'
"""Rank policies.

Each policy turns an enqueue attempt into an integer rank.  Attempts always
advance FIFO/WFQ rank state, even when the packet is later rejected by the
staging FIFO, so ``rank`` is called before admission is decided.

Every policy can snapshot and restore its full mutable state, and can produce
the certificate required by the final state report.
"""

from persist import PTrie

_SHIFT_SCALE = 1048576  # 2**20, WFQ finish-tag quantisation


class SchedulingAlgorithm:
    """Common interface implemented by the concrete rank policies."""

    def rank(self, pkt):
        raise NotImplementedError

    def post_service(self, rank):
        """Feedback for a successful service (WFQ virtual time)."""

    def snapshot(self):
        raise NotImplementedError

    def restore(self, state):
        raise NotImplementedError

    def certificate(self):
        raise NotImplementedError


class FifoAlgorithm(SchedulingAlgorithm):
    """``{"kind":"fifo"}``: a monotonically increasing arrival counter."""

    __slots__ = ('time',)

    def __init__(self):
        self.time = 0

    def rank(self, pkt):
        self.time += 1
        return self.time

    def snapshot(self):
        return self.time

    def restore(self, state):
        self.time = state

    def certificate(self):
        return {'kind': 'fifo', 'time': self.time}


class SpAlgorithm(SchedulingAlgorithm):
    """``{"kind":"sp"}``: static per-flow levels.

    The level table is fixed once the run starts, so it needs no versioning.
    """

    __slots__ = ('flowid2pri',)

    def __init__(self, flowid2pri):
        self.flowid2pri = dict(flowid2pri)

    def rank(self, pkt):
        return self.flowid2pri[pkt.flow]

    def snapshot(self):
        return None

    def restore(self, state):
        pass

    def certificate(self):
        table = self.flowid2pri
        return {'kind': 'sp',
                'levels': [[flow, table[flow]] for flow in sorted(table)]}


class pFabricAlgorithm(SchedulingAlgorithm):
    """``{"kind":"sff"}``: shortest flow size first (pFabric)."""

    __slots__ = ()

    def rank(self, pkt):
        return pkt.flow_size

    def snapshot(self):
        return None

    def restore(self, state):
        pass

    def certificate(self):
        return {'kind': 'sff'}


class WFQAlgorithm(SchedulingAlgorithm):
    """``{"kind":"wfq"}``: quantised finish tags with virtual time.

    ``F[flow] = max(F[flow], V) + ceil(length*2**20/weight[flow])``.  Both the
    weight and finish tables live in persistent tries keyed by the flow's rank
    in the sorted flow-id order, so a snapshot is two root pointers.
    """

    __slots__ = ('virtual_time', 'flows', 'index', 'bits',
                 'flowid2weight', 'flowid2finish')

    def __init__(self, flowid2weight):
        flows = sorted(flowid2weight)
        self.flows = flows
        self.virtual_time = 0
        bits = (len(flows) - 1).bit_length() if len(flows) > 1 else 1
        self.bits = bits
        self.index = {flow: pos for pos, flow in enumerate(flows)}
        items = [(pos, flowid2weight[flow]) for pos, flow in enumerate(flows)]
        self.flowid2weight = PTrie.fromitems(bits, items)
        self.flowid2finish = PTrie.fromitems(
            bits, [(pos, 0) for pos in range(len(flows))])

    def rank(self, pkt):
        pos = self.index[pkt.flow]
        weight = self.flowid2weight.get(pos, 1)
        finish = self.flowid2finish.get(pos, 0)
        virtual = self.virtual_time
        if finish < virtual:
            finish = virtual
        # exact integer ceil division; weights are 1..1024
        tag = finish + (pkt.length * _SHIFT_SCALE + weight - 1) // weight
        self.flowid2finish = self.flowid2finish.set(pos, tag)
        return tag

    def post_service(self, rank):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def set_weight(self, flow, weight):
        pos = self.index.get(flow)
        if pos is None:
            return False
        self.flowid2weight = self.flowid2weight.set(pos, weight)
        return True

    def snapshot(self):
        return (self.virtual_time, self.flowid2weight, self.flowid2finish)

    def restore(self, state):
        self.virtual_time, self.flowid2weight, self.flowid2finish = state

    def certificate(self):
        weights = self.flowid2weight
        finish = self.flowid2finish
        return {'kind': 'wfq',
                'virtual_time': self.virtual_time,
                'weights': [[flow, weights.get(pos)] for pos, flow in
                            enumerate(self.flows)],
                'finish': [[flow, finish.get(pos, 0)] for pos, flow in
                           enumerate(self.flows)]}


def make_policy(spec):
    """Build the policy object described by a request's ``policy`` value."""
    kind = spec['kind']
    if kind == 'fifo':
        return FifoAlgorithm()
    if kind == 'sp':
        return SpAlgorithm(spec['levels'])
    if kind == 'sff':
        return pFabricAlgorithm()
    if kind == 'wfq':
        return WFQAlgorithm(spec['weights'])
    raise ValueError('unknown policy kind: %r' % (kind,))
PYEOF
